-- =========================================================
-- LÀM CHA MẸ • DUY ANH LAB — Supabase schema + seed
-- Dán toàn bộ file này vào Supabase > SQL Editor > Run
-- =========================================================

-- 1) Bảng ứng dụng (dữ liệu sản phẩm hiển thị trên Trang Chủ & trang Chi tiết)
create table if not exists public.apps (
  id          text primary key,
  number      int  not null,
  name        text not null,
  stage_name  text not null,
  age_range   text not null,
  url         text not null,
  data        jsonb not null,          -- toàn bộ nội dung chi tiết (tính năng, pain points, video...)
  updated_at  timestamptz default now()
);

-- 2) Bảng yêu cầu tư vấn (INSERT từ form, UPDATE/DELETE ở trang Admin)
create table if not exists public.consultations (
  id          bigint generated always as identity primary key,
  full_name   text not null check (char_length(full_name) between 2 and 100),
  contact     text not null check (char_length(contact) between 5 and 120),
  topic       text not null default 'both',
  app_id      text references public.apps(id) on delete set null,
  message     text check (char_length(message) <= 2000),
  status      text not null default 'Mới' check (status in ('Mới','Đang xử lý','Đã liên hệ')),
  created_at  timestamptz default now()
);

-- 3) Bảng đánh giá app (INSERT ở trang Chi tiết, DELETE ở trang Admin)
create table if not exists public.reviews (
  id          bigint generated always as identity primary key,
  app_id      text not null references public.apps(id) on delete cascade,
  author_name text not null check (char_length(author_name) between 2 and 60),
  rating      int  not null check (rating between 1 and 5),
  content     text not null check (char_length(content) between 5 and 1000),
  created_at  timestamptz default now()
);

-- 4) Bảo mật RLS: khách chỉ được ĐỌC apps/reviews và GỬI (insert) tư vấn/đánh giá;
--    chỉ Admin (đăng nhập Supabase Auth) mới xem/sửa/xóa.
alter table public.apps          enable row level security;
alter table public.consultations enable row level security;
alter table public.reviews       enable row level security;

drop policy if exists "apps_read_all"        on public.apps;
drop policy if exists "apps_admin_write"     on public.apps;
drop policy if exists "consult_insert_all"   on public.consultations;
drop policy if exists "consult_admin_all"    on public.consultations;
drop policy if exists "reviews_read_all"     on public.reviews;
drop policy if exists "reviews_insert_all"   on public.reviews;
drop policy if exists "reviews_admin_delete" on public.reviews;

create policy "apps_read_all"        on public.apps          for select using (true);
create policy "apps_admin_write"     on public.apps          for all    to authenticated using (true) with check (true);
create policy "consult_insert_all"   on public.consultations for insert to anon, authenticated with check (status = 'Mới');
create policy "consult_admin_all"    on public.consultations for all    to authenticated using (true) with check (true);
create policy "reviews_read_all"     on public.reviews       for select using (true);
create policy "reviews_insert_all"   on public.reviews       for insert to anon, authenticated with check (true);
create policy "reviews_admin_delete" on public.reviews       for delete to authenticated using (true);

-- 5) Seed dữ liệu 4 ứng dụng
insert into public.apps (id, number, name, stage_name, age_range, url, data) values ('nuoi-duong-be-0-60', 1, $q$Nuôi Dưỡng Bé 0 - 60 Tháng$q$, $q$Khởi Đầu Vàng$q$, $q$0 – 5 Tuổi (0–60 Tháng)$q$, 'https://lamchame1.vercel.app', $json${"id":"nuoi-duong-be-0-60","number":1,"name":"Nuôi Dưỡng Bé 0 - 60 Tháng","stageName":"Khởi Đầu Vàng","ageRange":"0 – 5 Tuổi (0–60 Tháng)","educationStage":"Sơ Sinh & Mầm Non","url":"https://lamchame1.vercel.app","logoUrl":"/apps/nuoi-duong-be-0-60/app-logo.png","coverImage":"/apps/nuoi-duong-be-0-60/feature_01_home_dashboard_smart_logging.jpg","detailImages":["/apps/nuoi-duong-be-0-60/feature_01_home_dashboard_smart_logging.jpg","/apps/nuoi-duong-be-0-60/feature_02_growth_engine.jpg","/apps/nuoi-duong-be-0-60/feature_03_development_center.jpg","/apps/nuoi-duong-be-0-60/feature_04_nutrition_meal_planner.jpg","/apps/nuoi-duong-be-0-60/feature_05_offline_emergency_sos.jpg","/apps/nuoi-duong-be-0-60/feature_06_vaccination_smart_reminders.jpg","/apps/nuoi-duong-be-0-60/feature_07_digital_family_vault.jpg","/apps/nuoi-duong-be-0-60/feature_08_ai_parenting_companion.jpg","/apps/nuoi-duong-be-0-60/feature_09_activity_generator.jpg","/apps/nuoi-duong-be-0-60/feature_10_smart_family_timeline_journal.jpg"],"hookHeadline":"60 Tháng Đầu Đời Là Nền Móng Cho Cả Đời Người: Đừng Để Sự Lúng Túng Lấy Mất Khoảnh Khắc Bình An Của Con","hookQuestion":"Nửa đêm con sốt cao co giật hay hóc dị vật, bạn có kịp lục tìm Google giữa cơn hoảng loạn khi mạng chập chờn?","emotionalQuote":"Từ một giấc ngủ, một bữa ăn, một bước chân đầu tiên… đến những khoảnh khắc rất nhỏ mà sau này nhìn lại, cha mẹ sẽ thấy vô cùng đáng nhớ.","targetAudience":"Cha mẹ trẻ lần đầu có con, các gia đình đang nuôi dưỡng trẻ từ 0 đến 5 tuổi cần một người trợ lý khoa học, bảo mật và luôn sẵn sàng ngoại tuyến.","painPoints":["Bị ngợp giữa ma trận kiến thức bỉm sữa trái chiều trên mạng xã hội, không biết đâu là chuẩn khoa học.","Ghi chép cữ sữa, giờ ngủ, vệ sinh rời rạc trên giấy hoặc nhớ nhớ quên quên gây căng thẳng tinh thần.","Lúng túng mỗi ngày khi lên thực đơn ăn dặm (BLW, truyền thống, kiểu Nhật) từ những nguyên liệu sẵn có trong tủ lạnh.","Hoang mang không biết con có phát triển đúng chuẩn vận động và ngôn ngữ hay không.","Mất bình tĩnh khi xảy ra sự cố cấp bách (sốt cao, hóc nghẹn, bỏng) và không có cẩm nang sơ cứu mở tức thì khi mất mạng."],"coreSolution":"Ứng dụng Cha Mẹ 0–60 tích hợp 10 tính năng cốt lõi công nghệ PWA ngoại tuyến toàn diện, nhật ký 1 chạm bằng giọng nói, công cụ tính chuẩn tăng trưởng WHO, gợi ý món ăn dặm từ tủ lạnh nhà mình và nút cứu trợ SOS khẩn cấp.","keyFeatures":[{"title":"Màn Hình Trung Tâm 'Hôm Nay' & Ghi Chép Nhanh","description":"Trả lời câu hỏi 'Hôm nay con cần gì?' với 3 việc trọng tâm, nhật ký ăn ngủ vệ sinh 1 chạm hoặc nhập bằng giọng nói tiếng Việt.","iconName":"Clock"},{"title":"Bộ Đo Tăng Trưởng Thể Chất Chuẩn Khoa Học","description":"Quản lý cân nặng, chiều cao, vòng đầu theo chuẩn tăng trưởng WHO, biểu đồ trực quan kèm phân tích trung lập không phán xét.","iconName":"TrendingUp"},{"title":"Trung Tâm 5 Mốc Phát Triển Toàn Diện","description":"Đánh giá sự tiến bộ qua 5 lĩnh vực: Giao tiếp, Vận động thô, Vận động tinh, Nhận thức, Cá nhân - Xã hội kèm hướng dẫn quan sát dịu dàng.","iconName":"Sparkles"},{"title":"Gợi Ý Ăn Dặm 'Tủ Lạnh Nhà Mình Có Gì?'","description":"Lên thực đơn ăn dặm theo phương pháp truyền thống, BLW, kiểu Nhật; tự động tạo công thức món ăn giàu dinh dưỡng từ nguyên liệu sẵn có.","iconName":"Utensils"},{"title":"Nút Cấp Cứu SOS Ngoại Tuyến 100%","description":"Nút floating SOS mở tức thì quy trình sơ cứu chuẩn (hóc dị vật Heimlich, co giật, bỏng, sốt cao) không cần kết nối mạng.","iconName":"ShieldAlert"},{"title":"Lịch Tiêm Chủng & Nhắc Lịch Thông Minh","description":"Quản lý tiêm chủng mở rộng và vắc xin dịch vụ, cài đặt nhắc nhở uống thuốc, khám định kỳ và vệ sinh hàng ngày.","iconName":"Calendar"},{"title":"Ví Số Hóa Hồ Sơ & Giấy Tờ Bé Xuất PDF","description":"Quét và lưu trữ an toàn BHYT, sổ tiêm, đơn thuốc trên máy; xuất phiếu y tế định dạng PDF chuẩn 1 chạm khi đưa bé đi khám.","iconName":"FileText"},{"title":"Trợ Lý AI Đồng Hành Chuyên Biệt","description":"Giải đáp thắc mắc khoa học, chuẩn bị sẵn bộ câu hỏi khi gặp bác sĩ nhi khoa, dẫn nguồn y khoa minh bạch.","iconName":"Bot"},{"title":"Bộ Tạo Trò Chơi 'Chơi Cùng Con 10 Phút'","description":"Gợi ý các trò chơi tương tác kích thích trí não theo độ tuổi dựa trên vật dụng đơn giản sẵn có trong nhà.","iconName":"Gamepad2"},{"title":"Dòng Thời Gian & Nhật Ký Kỷ Niệm Gia Đình","description":"Tổng hợp toàn bộ chỉ số, mốc phát triển và hình ảnh kỷ niệm thành một dòng thời gian dài hạn xuyên suốt 5 năm đầu đời.","iconName":"BookOpen"}],"uniqueHighlights":["PWA Ngoại tuyến 100% - Dữ liệu lưu cục bộ bảo mật tuyệt đối","Không yêu cầu tạo tài khoản phức tạp, vào là dùng ngay","Gợi ý thực đơn ăn dặm thông minh theo tủ lạnh gia đình","Quy trình sơ cứu khẩn cấp cứu mạng trong tích tắc"],"videoDuration":"2:45","videoTagline":"10 tính năng cốt lõi của ứng dụng Nuôi dưỡng bé 0–60 tháng đồng hành cùng gia đình Việt Nam chăm sóc và lưu giữ hành trình khôn lớn của con","videoScenes":[{"time":"0:00","title":"Màn hình trung tâm \"Hôm nay\" & Ghi chép nhanh (Home Dashboard & Smart Logging)","description":"Ứng dụng \"Cha Mẹ 0–60\" được thiết kế với 10 tính năng cốt lõi nhằm đồng hành cùng gia đình Việt Nam trong việc chăm sóc và theo dõi sự phát triển của trẻ từ 0 đến 60 tháng tuổi: Giải đáp câu hỏi \"Hôm nay con cần gì\" bằng cách hiển thị 3 việc quan trọng trong ngày, trạng thái sinh hoạt (ăn, ngủ, vệ sinh) và công cụ ghi nhận nhanh 1 chạm hoặc nhập bằng giọng nói."},{"time":"0:15","title":"Theo dõi tăng trưởng thể chất (Growth Engine)","description":"Quản lý các chỉ số cân nặng, chiều cao, vòng đầu theo chuẩn tăng trưởng, minh họa xu hướng phát triển trực quan và đưa ra lời khuyên trung lập mà không tự ý chẩn đoán."},{"time":"0:30","title":"Trung tâm mốc phát triển (Development Center)","description":"Theo dõi sự tiến bộ của bé qua 5 lĩnh vực (Giao tiếp, Vận động thô, Vận động tinh, Nhận thức, Cá nhân – Xã hội) kèm các lưu ý quan sát nhẹ nhàng, giúp cha mẹ bớt lo âu."},{"time":"0:45","title":"Gợi ý dinh dưỡng & Quản lý thực đơn (Nutrition & Meal Planner)","description":"Hỗ trợ nhiều phương pháp ăn dặm (Truyền thống, BLW, Kiểu Nhật), cá nhân hóa theo độ tuổi/dị ứng, kết hợp tính năng \"Tủ lạnh nhà mình có gì\" để tự động gợi ý món ăn phù hợp với nguyên liệu sẵn có."},{"time":"1:00","title":"Nút khẩn cấp SOS ngoại tuyến (Offline Emergency SOS)","description":"Nút floating SOS luôn hiển thị để truy cập tức thì các hướng dẫn xử lý sơ cứu khẩn cấp (hóc dị vật, sốt/co giật, bỏng, chấn thương...), đảm bảo hoạt động bình thường ngay cả khi không có kết nối internet."},{"time":"1:15","title":"Lịch tiêm chủng & Nhắc lịch thông minh (Vaccination & Smart Reminders)","description":"Quản lý lịch tiêm (Chương trình Mở rộng & Tiêm dịch vụ), đồng thời cài đặt nhắc lịch uống thuốc, khám bệnh, đánh răng và các sinh hoạt hằng ngày."},{"time":"1:30","title":"Ví hồ sơ gia đình kỹ thuật số (Digital Family Vault & Document Scanner)","description":"Quét, lưu trữ và bảo mật các giấy tờ quan trọng của bé (BHYT, phiếu tiêm, đơn thuốc), hỗ trợ xuất file PDF 1 chạm để mang đi khám bệnh hoặc nhập học."},{"time":"1:45","title":"Trợ lý AI đồng hành cùng cha mẹ (AI Parenting Companion)","description":"Trả lời các thắc mắc chăm sóc con, hỗ trợ chuẩn bị câu hỏi cho bác sĩ, giải thích thông tin y tế dễ hiểu và luôn dẫn nguồn minh bạch."},{"time":"2:00","title":"Bộ tạo hoạt động \"Chơi cùng con 10 phút\" (Activity Generator)","description":"Gợi ý các trò chơi tương tác phát triển theo độ tuổi (0–60 tháng) dựa trên quỹ thời gian rảnh và vật dụng đơn giản có sẵn trong nhà."},{"time":"2:15","title":"Dòng thời gian & Nhật ký gia đình (Smart Family Timeline & Journal)","description":"Tổng hợp dữ liệu sức khỏe, mốc phát triển, tiêm chủng cùng hình ảnh và khoảnh khắc đáng nhớ thành một dòng thời gian dài hạn xuyên suốt quá trình khôn lớn của trẻ."},{"time":"2:30","title":"Lời bình & Đồng hành trọn vẹn hành trình 0–60 tháng","description":"Từ một giấc ngủ, một bữa ăn, một bước chân đầu tiên… đến những khoảnh khắc rất nhỏ mà sau này nhìn lại, cha mẹ sẽ thấy vô cùng đáng nhớ. Cùng con lớn lên từng ngày – và cùng nhau lưu giữ hành trình 0–60 tháng thật trọn vẹn."}],"theme":{"from":"from-rose-500","to":"to-amber-500","accent":"text-rose-400","badgeBg":"bg-rose-500/10","badgeText":"text-rose-300","badgeBorder":"border-rose-500/30","glowColor":"rgba(244, 63, 94, 0.35)","buttonGradient":"from-rose-500 via-pink-500 to-amber-500"}}$json$::jsonb)
on conflict (id) do update set number=excluded.number, name=excluded.name, stage_name=excluded.stage_name, age_range=excluded.age_range, url=excluded.url, data=excluded.data, updated_at=now();

insert into public.apps (id, number, name, stage_name, age_range, url, data) values ('nuoi-day-tre-6-11', 2, $q$Nuôi Dạy Con 6 Đến 11 Tuổi$q$, $q$Vững Bước Tiểu Học$q$, $q$6 – 11 Tuổi (Lớp 1 Đến Lớp 5)$q$, 'https://lamchame2.vercel.app', $json${"id":"nuoi-day-tre-6-11","number":2,"name":"Nuôi Dạy Con 6 Đến 11 Tuổi","stageName":"Vững Bước Tiểu Học","ageRange":"6 – 11 Tuổi (Lớp 1 Đến Lớp 5)","educationStage":"Bậc Tiểu Học Toàn Diện","url":"https://lamchame2.vercel.app","logoUrl":"/apps/nuoi-day-tre-6-11/app-logo.png","coverImage":"/apps/nuoi-day-tre-6-11/feature_01_ai_companion_247.jpg","detailImages":["/apps/nuoi-day-tre-6-11/feature_01_ai_companion_247.jpg","/apps/nuoi-day-tre-6-11/feature_02_parenting_scripts.jpg","/apps/nuoi-day-tre-6-11/feature_03_home_dashboard.jpg","/apps/nuoi-day-tre-6-11/feature_04_child_profile.jpg","/apps/nuoi-day-tre-6-11/feature_05_academic_knowledge_graph.jpg","/apps/nuoi-day-tre-6-11/feature_06_emotional_observation.jpg","/apps/nuoi-day-tre-6-11/feature_07_digital_family_manager.jpg","/apps/nuoi-day-tre-6-11/feature_08_health_nutrition.jpg","/apps/nuoi-day-tre-6-11/feature_09_family_routine_quality_time.jpg","/apps/nuoi-day-tre-6-11/feature_10_weekly_review_sos_zone.jpg"],"hookHeadline":"Bàn Học Có Đang Trở Thành 'Chiến Trường'? Hãy Dừng La Mắng Để Bắt Đầu Thấu Hiểu Cùng Con Mỗi Tối","hookQuestion":"Mỗi tối ngồi vào bàn học cùng con có biến thành cơn ác mộng la hét? Bạn đang dạy con học hay đang làm con sợ hãi việc học cả đời?","emotionalQuote":"Con không cần một giám thị chấm điểm mỗi tối; con cần một ngọn hải đăng bình tĩnh soi sáng những lúc con bế tắc.","targetAudience":"Cha mẹ có con đang học Lớp 1 đến Lớp 5, đang đối diện với áp lực bài vở, thói quen trì hoãn, nghiện màn hình điện thoại và sự thay đổi cảm xúc của con.","painPoints":["Mỗi tối dạy con học đều biến thành cãi vã, mất kiên nhẫn dẫn đến la mắng rồi lại tự trách bản thân.","Vô tình so sánh điểm số của con với bạn bè, tạo áp lực vô hình khiến con tự ti và xa cách cha mẹ.","Không biết cách xử lý khi con nghiện xem Youtube, chơi Roblox mà không muốn biến thành kẻ cấm đoán độc đoán.","Không phát hiện được lỗ hổng kiến thức gốc của con ở môn Toán, Tiếng Việt nên càng bắt làm bài tập con càng bế tắc.","Cha mẹ căng thẳng quá tải sau ngày làm việc dài, thiếu công cụ 'hạ nhiệt' khi cơn giận bùng phát."],"coreSolution":"Ứng dụng Nuôi Dạy Con 6–11 Tuổi trang bị Thư viện Kịch bản Giao tiếp (Parenting Scripts) chuyển đổi câu từ đối lập, Đồ thị kiến thức lớp 1-5 truy vết nguyên nhân mất gốc, Hồ sơ con không KPI điểm số và Nút hạ nhiệt SOS 60 giây.","keyFeatures":[{"title":"Trợ Lý AI 24/7 Phân Tích Tình Huống Nuôi Dạy","description":"Hội thoại giải đáp các tình huống thực tế theo khung: phân tích nguyên nhân, điều cần quan sát, câu nên nói và hoạt động 5 phút.","iconName":"Bot"},{"title":"Thư Viện Kịch Bản Giao Tiếp (Parenting Scripts)","description":"Đối chiếu trực quan câu nói dễ gây căng thẳng (❌) và cách nói thay thế thấu cảm (✅) khi con lười học, nổi nóng hay trì hoãn.","iconName":"MessageSquareQuote"},{"title":"Trang Tổng Quan & Điểm Tin AI Hàng Ngày","description":"Giải đáp 'Hôm nay cha mẹ nên biết gì về con?', hiển thị 3 trọng tâm đồng hành và khung kết nối '2 phút cùng con' mỗi sáng/tối.","iconName":"Sun"},{"title":"Hồ Sơ Con Phác Họa Bức Tranh Không KPI","description":"Mô tả toàn diện sự tự tin, độ tập trung, thói quen đọc sách và cảm xúc của con mà không chấm điểm hay xếp hạng so sánh.","iconName":"UserCheck"},{"title":"Hỗ Trợ Học Tập & Đồ Thị Kiến Thức Lớp 1-5","description":"Bám sát chương trình Toán, Tiếng Việt, Tiếng Anh; tự động truy vết các lỗ hổng kiến thức nền tảng (prerequisites) để hỗ trợ đúng chỗ.","iconName":"Network"},{"title":"Nhật Ký Cảm Xúc & Nhận Diện Quy Luật Hành Vi","description":"Ghi nhận trạng thái tâm lý hàng ngày của con; hệ thống tự động phát hiện mẫu hình quy luật và khung giờ con dễ căng thẳng.","iconName":"HeartPulse"},{"title":"Quản Lý Thói Quen Số & Thỏa Thuận Gia Đình","description":"Xây dựng 'Thỏa thuận công nghệ gia đình' tự nguyện, theo dõi thời lượng dùng màn hình và kịch bản đối thoại thay vì cấm đoán.","iconName":"Smartphone"},{"title":"Sức Khỏe & Dinh Dưỡng 'Ăn Gì Cho Con?'","description":"Theo dõi chiều cao, cân nặng, giấc ngủ; gợi ý thực đơn tuần và bữa sáng nhanh 15 phút đủ năng lượng cho trẻ tiểu học.","iconName":"Apple"},{"title":"Nhịp Sống & Hoạt Động Kết Nối 5–15 Phút","description":"Thư viện trò chuyện, đọc sách, nấu ăn, dạo bộ ngắn giúp gắn kết tình cảm gia đình sau giờ tan trường căng thẳng.","iconName":"Smile"},{"title":"Review Tuần Ngọn Hải Đăng & Nút Hạ Nhiệt SOS 60s","description":"Điểm sáng tiến bộ tuần qua góc nhìn tích cực kết hợp nút SOS 60 giây (nhạc sóng não Alpha + nhịp thở) giúp cha mẹ bình tĩnh tức thì.","iconName":"ShieldAlert"}],"uniqueHighlights":["Bộ kịch bản nói chuyện thay thế câu la mắng hiệu quả tức thì","Đồ thị truy vết kiến thức giúp con không còn sợ môn Toán","Nút SOS 60 giây cứu nguy những cơn bốc hỏa của cha mẹ","Triết lý nuôi dạy không KPI, nuôi dưỡng nội lực tự tin"],"videoDuration":"2:50","videoTagline":"10 tính năng cốt lõi của ứng dụng Nuôi dạy con 6–11 tuổi giúp cha mẹ tự tin đồng hành cùng con từ lớp 1 đến hết Tiểu học","videoScenes":[{"time":"0:00","title":"Trợ lý AI 24/7 đồng hành cùng cha mẹ (AI Parenting Companion)","description":"5 năm đầu đời trôi qua thật nhanh. Khi con bước vào Tiểu học, cha mẹ cũng bước sang một hành trình mới: đồng hành cùng con học tập, quản lý thời gian, công nghệ và cảm xúc. Nuôi Dạy Con 6–11 Tuổi với 10 tính năng cốt lõi được thiết kế chuyên biệt: Trợ lý AI chuyên biệt giải đáp các tình huống thực tế theo khung phân tích nguyên nhân, điều cần quan sát, gợi ý câu nói và hoạt động 5–10 phút."},{"time":"0:15","title":"Thư viện kịch bản giao tiếp (Parenting Scripts)","description":"Cung cấp danh mục câu nói tình huống (khi con không chịu học, nổi nóng, dùng điện thoại nhiều, trì hoãn...) với sự so sánh trực quan giữa câu nói dễ gây căng thẳng (❌) và cách nói thay thế tích cực (✅)."},{"time":"0:30","title":"Trang tổng quan & Điểm tin hàng ngày (Home Dashboard & AI Daily Briefing)","description":"Trả lời câu hỏi 'Hôm nay cha mẹ nên biết gì về con?', hiển thị 3 trọng tâm đồng hành trong tuần, gợi ý hành động thực tế từ AI và khung kết nối '2 phút cùng con' vào buổi sáng hoặc tối."},{"time":"0:45","title":"Hồ sơ phác họa bức tranh phát triển của con (Child Profile)","description":"Phản ánh toàn diện sự phát triển của con qua các chỉ số mô tả (độ tự tin học tập, mức độ tập trung, thói quen đọc sách, giấc ngủ, cảm xúc...) thay vì chấm điểm hay so sánh, xếp hạng giữa các trẻ."},{"time":"1:00","title":"Hỗ trợ học tập & Đồ thị kiến thức (Academic Support Engine & Knowledge Graph)","description":"Bám sát chương trình từ Lớp 1 đến Lớp 5 cho các môn Toán, Tiếng Việt, Tiếng Anh; tự động truy vết các lỗ hổng kiến thức nền tảng (prerequisites) để gợi ý hoạt động ngắn giúp cha mẹ đồng hành cùng con."},{"time":"1:15","title":"Nhật ký quan sát Cảm xúc & Hành vi (Emotional & Behavior Observation)","description":"Cho phép cha mẹ ghi nhận trạng thái cảm xúc hàng ngày của con (vui, lo lắng, bực bội...) và hệ thống tự động nhận diện mẫu hình quy luật theo thời gian, phát hiện khung giờ con thường dễ căng thẳng."},{"time":"1:30","title":"Quản lý Thói quen Số & Thiết bị (Digital Family Manager)","description":"Giúp thiết lập 'Thỏa thuận công nghệ gia đình' (Family Digital Agreement), theo dõi thời gian sử dụng màn hình/chơi game và cung cấp kịch bản trò chuyện thay vì cấm đoán cứng nhắc."},{"time":"1:45","title":"Theo dõi Sức khỏe, Thể chất & Dinh dưỡng (Health & Nutrition)","description":"Biểu đồ theo dõi chiều cao, cân nặng, giấc ngủ, vận động cùng tính năng 'Ăn gì cho con?' gợi ý thực đơn tuần và bữa sáng nhanh 15 phút phù hợp với gia đình Việt."},{"time":"2:00","title":"Thiết lập Nhịp sống & Hoạt động kết nối gia đình (Family Routine & Quality Time)","description":"Xây dựng thói quen sinh hoạt cân bằng và cung cấp thư viện gợi ý các hoạt động kết nối 5–15 phút (đọc sách, nấu ăn, đi dạo, trò chuyện) cá nhân hóa theo độ tuổi và năng lượng của gia đình."},{"time":"2:15","title":"Báo cáo nhìn lại hàng tuần & Zone hạ nhiệt SOS (Weekly Family Review & SOS Cool-down Zone)","description":"Tổng kết 5–7 điểm sáng tiến bộ và xu hướng phát triển hàng tuần qua góc nhìn 'Ngọn Hải Đăng', kết hợp nút hạ nhiệt SOS 60 giây (nhạc Alpha + bài tập thở) giúp cha mẹ giải tỏa căng thẳng khi dạy con học."},{"time":"2:30","title":"Lời bình & Đồng hành ý nghĩa bên con","description":"Hy vọng ứng dụng sẽ trở thành một người bạn đồng hành nhỏ, giúp cha mẹ có thêm góc nhìn, thêm công cụ và thêm những phút kết nối ý nghĩa bên con."}],"theme":{"from":"from-emerald-500","to":"to-teal-500","accent":"text-emerald-400","badgeBg":"bg-emerald-500/10","badgeText":"text-emerald-300","badgeBorder":"border-emerald-500/30","glowColor":"rgba(16, 185, 129, 0.35)","buttonGradient":"from-emerald-500 via-teal-500 to-cyan-500"}}$json$::jsonb)
on conflict (id) do update set number=excluded.number, name=excluded.name, stage_name=excluded.stage_name, age_range=excluded.age_range, url=excluded.url, data=excluded.data, updated_at=now();

insert into public.apps (id, number, name, stage_name, age_range, url, data) values ('thau-hieu-thieu-nien-12-15', 3, $q$Thấu Hiểu Thiếu Niên 12 Đến 15 Tuổi$q$, $q$Vượt Bão Dậy Thì$q$, $q$12 – 15 Tuổi (Lớp 6 Đến Lớp 9)$q$, 'https://lamchame3.vercel.app', $json${"id":"thau-hieu-thieu-nien-12-15","number":3,"name":"Thấu Hiểu Thiếu Niên 12 Đến 15 Tuổi","stageName":"Vượt Bão Dậy Thì","ageRange":"12 – 15 Tuổi (Lớp 6 Đến Lớp 9)","educationStage":"Bậc Trung Học Cơ Sở (THCS)","url":"https://lamchame3.vercel.app","logoUrl":"/apps/thau-hieu-thieu-nien-12-15/app-logo.png","coverImage":"/apps/thau-hieu-thieu-nien-12-15/feature_01_onboarding_projector.jpg","detailImages":["/apps/thau-hieu-thieu-nien-12-15/feature_01_onboarding_projector.jpg","/apps/thau-hieu-thieu-nien-12-15/feature_02_tanner_nutrition.jpg","/apps/thau-hieu-thieu-nien-12-15/feature_03_emotional_first_aid_nvc.jpg","/apps/thau-hieu-thieu-nien-12-15/feature_04_cyber_safety_grooming.jpg","/apps/thau-hieu-thieu-nien-12-15/feature_05_legal_framework_age_14.jpg","/apps/thau-hieu-thieu-nien-12-15/feature_06_holland_career_9plus.jpg","/apps/thau-hieu-thieu-nien-12-15/feature_07_family_agreement_matrix.jpg","/apps/thau-hieu-thieu-nien-12-15/feature_08_ai_dialogue_simulator.jpg","/apps/thau-hieu-thieu-nien-12-15/feature_09_thcs_curriculum_6to9.jpg","/apps/thau-hieu-thieu-nien-12-15/feature_10_family_connection.jpg"],"hookHeadline":"Con Bắt Đầu Đóng Chặt Cửa Phòng Và Coi Lời Cha Mẹ Là Phiền Phức: Bạn Chọn Phá Cửa Hay Học Cách Lắng Nghe?","hookQuestion":"Bạn có biết con mình đang nói chuyện với ai trên mạng lúc 11 giờ đêm? Liệu con có đang là nạn nhân của bẫy thao túng tâm lý (Grooming) mà không dám mở lời?","emotionalQuote":"12–15 tuổi: Con không còn là một đứa trẻ, nhưng cũng chưa phải là người lớn. Đừng để cánh cửa phòng con đóng lại vĩnh viễn với thế giới của cha mẹ.","targetAudience":"Cha mẹ có con trong giai đoạn dậy thì THCS (Lớp 6 đến Lớp 9), thầy cô giáo và người giám hộ cần phương pháp giao tiếp thấu cảm và tấm khiên bảo vệ con trên không gian mạng.","painPoints":["Con thay đổi tính nết đột ngột: khép kín, cáu gắt, chống đối và xa lánh mọi câu hỏi quan tâm của cha mẹ.","Nỗi sợ hãi tột cùng về cạm bẫy không gian mạng: Grooming (kẻ xấu dụ dỗ), Sextortion (tống tiền ảnh nhạy cảm), bạo lực mạng.","Cha mẹ tò mò xem lén nhật ký, tin nhắn của con dẫn đến đổ vỡ niềm tin hoàn toàn và xung đột dữ dội.","Băn khoăn về thể chất dậy thì, tăng trưởng chiều cao có kịp thang Tanner vàng hay không.","Hoang mang trước kỳ thi chuyển cấp Lớp 9 vào Lớp 10 và định hướng phân luồng nghề nghiệp 9+."],"coreSolution":"Trợ lý số hóa cung cấp Bộ sơ cứu cảm xúc & Kịch bản giao tiếp phi bạo lực NVC 4 bước, Tấm khiên an toàn số chống bẫy mạng & hotline 111, Khung nhận thức pháp lý tuổi 14, Trắc nghiệm Holland RIASEC và Giả lập đối thoại AI.","keyFeatures":[{"title":"Giao Diện Đa Nền Tảng & Chế Độ Máy Chiếu Phòng Khách","description":"Đồng bộ trải nghiệm trên điện thoại, máy tính và máy chiếu gia đình để cha mẹ và con cùng ngồi lại trao đổi cởi mở.","iconName":"Tv"},{"title":"Bứt Phá Tầm Vóc & Dinh Dưỡng Thang Tanner Dậy Thì","description":"Theo dõi 5 giai đoạn tăng trưởng thể chất Tanner, tối ưu hóa dinh dưỡng Canxi D3K2, giấc ngủ và chế độ vận động bứt phá chiều cao.","iconName":"TrendingUp"},{"title":"Bộ Sơ Cứu Cảm Xúc & Kịch Bản Giao Tiếp NVC 4 Bước","description":"Khung giao tiếp phi bạo lực: Quan sát, Cảm nhận, Nhu cầu và Đề xuất giúp xoa dịu xung đột ngay khi con nổi giận hoặc khép mình.","iconName":"HeartHandshake"},{"title":"Tấm Khiên An Toàn Số & Chống Bẫy Grooming / Sextortion","description":"Trang bị bộ quy tắc 4 KHÔNG trên mạng, nhận diện chiêu trò thao túng tình cảm, cảnh báo mã độc và kết nối nhanh Tổng đài quốc gia 111.","iconName":"ShieldCheck"},{"title":"Mốc Nhận Thức Pháp Lý Tuổi 14 & Ranh Giới Cá Nhân","description":"Trang bị kiến thức pháp lý công dân tuổi 14 (quyền riêng tư, trách nhiệm hành vi) giúp cha mẹ ứng xử văn minh và tôn trọng con.","iconName":"Scale"},{"title":"Trắc Nghiệm Holland RIASEC Hướng Nghiệp Phân Luồng 9+","description":"Đánh giá 6 nhóm tính cách nghề nghiệp Holland, vạch rõ con đường thi Cấp 3 chuyên/công lập hoặc mô hình phân luồng đào tạo nghề 9+.","iconName":"Compass"},{"title":"Ma Trận Cam Kết & Phần Thưởng Tự Chủ 2 Chiều","description":"Thiết lập văn bản thỏa thuận gia đình minh bạch; mở khóa phần thưởng con khao khát (decor phòng, chơi game, sách truyện) khi hoàn thành cam kết.","iconName":"Award"},{"title":"Giả Lập Đối Thoại AI Cố Vấn Cha Mẹ","description":"Không gian thực hành giao tiếp an toàn: Cha mẹ nhập thử điều muốn nói, AI đóng vai con và đưa ra phản hồi thực tế để tinh chỉnh lời ăn tiếng nói.","iconName":"Bot"},{"title":"Hệ Thống Hóa Chương Trình Giáo Dục THCS (Lớp 6–9)","description":"Cung cấp chi tiết mục tiêu kiến thức các môn học trọng tâm ở từng khối lớp giúp cha mẹ nắm bắt lộ trình học tập của con.","iconName":"GraduationCap"},{"title":"Cầu Nối Thấu Hiểu & Gắn Kết Yêu Thương Gia Đình","description":"Chuyển hóa khủng hoảng dậy thì thành cơ hội thấu hiểu sâu sắc, tạo điểm tựa bình yên nhất để con tự tin trưởng thành.","iconName":"Sparkles"}],"uniqueHighlights":["Tấm khiên an toàn mạng số 1 cho học sinh THCS và kết nối Tổng đài 111","Thực hành giả lập hội thoại với AI trước khi nói chuyện thật với con","Kịch bản giao tiếp phi bạo lực NVC biến cãi vã thành thấu hiểu","Định hướng phân luồng 9+ chuẩn khoa học từ trắc nghiệm Holland"],"videoDuration":"2:55","videoTagline":"10 tính năng cốt lõi đồng hành bình tĩnh và thấu hiểu thiếu niên 12–15 tuổi – Cầu nối yêu thương tuổi dậy thì","videoScenes":[{"time":"0:00","title":"Onboarding Đa Nền Tảng & Chế Độ Máy Chiếu","description":"12–15 tuổi – con không còn là một đứa trẻ, nhưng cũng chưa thực sự là một người lớn. Sau Nuôi dưỡng bé 0–60 tháng và Nuôi dạy con 6–11 tuổi, đây là giai đoạn con thay đổi rất nhanh: cơ thể, cảm xúc, suy nghĩ, bạn bè, công nghệ và cả cách con nhìn về chính mình. Thấu hiểu thiếu niên 12–15 tuổi với 10 tính năng cốt lõi: Dễ dàng truy cập ứng dụng trên mọi thiết bị từ điện thoại, laptop đến máy chiếu gia đình, giao diện trực quan mượt mà."},{"time":"0:15","title":"Bứt Phá Tầm Vóc & Dinh Dưỡng Dậy Thì","description":"Theo dõi sát sao biểu đồ tăng trưởng chiều cao theo thang Tanner. Ứng dụng gợi ý chế độ dinh dưỡng Canxi D3K2, bài tập vận động và giấc ngủ chuẩn khoa học cho tuổi dậy thì."},{"time":"0:30","title":"Bộ Sơ Cứu Cảm Xúc & Tạo Kịch Bản NVC","description":"Xóa tan căng thẳng tức thì với 4 bước giao tiếp phi bạo lực NVC: Quan sát, Cảm nhận, Nhu cầu và Đề xuất. Cầu nối giúp cha mẹ và con lắng nghe, xoa dịu cảm xúc chân thành."},{"time":"0:45","title":"An Toàn Số & Chống Bẫy Grooming / Sextortion","description":"Tấm khiên bảo vệ kỹ thuật số toàn diện cho con trên không gian mạng. Trang bị bộ quy tắc 4 KHÔNG, cảnh báo bẫy Grooming và kết nối nhanh Tổng đài quốc gia 111."},{"time":"1:00","title":"Mốc Pháp Lý Tuổi 14 & Quyền Riêng Tư Số","description":"Tôn trọng ranh giới cá nhân và quyền riêng tư của con. Cung cấp khung nhận thức pháp lý tuổi 14, giúp cha mẹ ứng xử chuẩn mực và xây dựng niềm tin bền chặt."},{"time":"1:15","title":"Hướng Nghiệp Holland RIASEC & Phân Luồng 9+","description":"Khám phá tiềm năng vượt trội của con qua bài test Holland 6 nhóm tính cách. Định hướng rõ ràng hai con đường Cấp 3 hoặc Phân luồng 9+ ngay từ cột mốc 15 tuổi."},{"time":"1:30","title":"Ma Trận Cam Kết & Phần Thưởng 2 Chiều","description":"Thiết lập thỏa thuận gia đình minh bạch và công bằng. Mở khóa các phần thưởng tự chủ như decor phòng, chơi game, sách truyện khi con hoàn thành cam kết."},{"time":"1:45","title":"Giả Lập Đối Thoại AI Cố Vấn","description":"Không gian thực hành giao tiếp an toàn cho cha mẹ. Trợ lý AI đóng vai trò cố vấn, đưa ra phản hồi thời gian thực giúp cha mẹ luyện tập trước khi đối thoại cùng con."},{"time":"2:00","title":"Tổng Hợp Chương Trình Giáo Dục THCS (Lớp 6 – Lớp 9)","description":"Hệ thống hóa toàn bộ chương trình giáo dục từ lớp 6 đến lớp 9. Cung cấp chi tiết các môn học, quy định chuẩn và mục tiêu kiến thức trọng tâm con cần nắm vững ở từng cấp lớp."},{"time":"2:15","title":"Cầu Nối Thấu Hiểu & Kết Nối Gia Đình","description":"Chuyển hóa xung đột thành sự gắn kết sâu sắc. Cùng con bước qua tuổi dậy thì rực rỡ, đong đầy yêu thương và sự thấu hiểu trọn vẹn giữa cha mẹ và con cái."},{"time":"2:30","title":"Thấu hiểu để đồng hành – Cùng con tự tin lớn lên","description":"Hy vọng Thấu hiểu thiếu niên 12–15 tuổi sẽ trở thành một cây cầu nhỏ, giúp cha mẹ và con gần nhau hơn giữa những thay đổi của tuổi dậy thì. Thấu hiểu để đồng hành – đồng hành để con tự tin lớn lên."}],"theme":{"from":"from-cyan-500","to":"to-blue-600","accent":"text-cyan-400","badgeBg":"bg-cyan-500/10","badgeText":"text-cyan-300","badgeBorder":"border-cyan-500/30","glowColor":"rgba(6, 182, 212, 0.35)","buttonGradient":"from-cyan-500 via-blue-500 to-indigo-600"}}$json$::jsonb)
on conflict (id) do update set number=excluded.number, name=excluded.name, stage_name=excluded.stage_name, age_range=excluded.age_range, url=excluded.url, data=excluded.data, updated_at=now();

insert into public.apps (id, number, name, stage_name, age_range, url, data) values ('dinh-huong-thanh-nien-16-18', 4, $q$Định Hướng Thanh Niên 16 Đến 18 Tuổi$q$, $q$Trưởng Thành Vững Vàng$q$, $q$16 – 18 Tuổi (Lớp 10 Đến Lớp 12)$q$, 'https://lamchame4.vercel.app', $json${"id":"dinh-huong-thanh-nien-16-18","number":4,"name":"Định Hướng Thanh Niên 16 Đến 18 Tuổi","stageName":"Trưởng Thành Vững Vàng","ageRange":"16 – 18 Tuổi (Lớp 10 Đến Lớp 12)","educationStage":"Bậc Trung Học Phổ Thông (THPT)","url":"https://lamchame4.vercel.app","logoUrl":"/apps/dinh-huong-thanh-nien-16-18/app-logo.png","coverImage":"/apps/dinh-huong-thanh-nien-16-18/feature_01_home_dashboard_weekly_insight.jpg","detailImages":["/apps/dinh-huong-thanh-nien-16-18/feature_01_home_dashboard_weekly_insight.jpg","/apps/dinh-huong-thanh-nien-16-18/feature_02_academic_exam_hub.jpg","/apps/dinh-huong-thanh-nien-16-18/feature_03_career_future_direction.jpg","/apps/dinh-huong-thanh-nien-16-18/feature_04_parent_teen_connection.jpg","/apps/dinh-huong-thanh-nien-16-18/feature_05_ai_communication_assistant.jpg","/apps/dinh-huong-thanh-nien-16-18/feature_06_family_boundary_builder.jpg","/apps/dinh-huong-thanh-nien-16-18/feature_07_health_wellness_tracker.jpg","/apps/dinh-huong-thanh-nien-16-18/feature_08_digital_life_guidance.jpg","/apps/dinh-huong-thanh-nien-16-18/feature_09_age18_citizenship_prep.jpg","/apps/dinh-huong-thanh-nien-16-18/feature_10_ai_companion_family_journal.jpg"],"hookHeadline":"Chuyển Từ 'Quản Lý' Sang 'Trao Quyền': Chuẩn Bị Hành Trang Để Con Vững Vàng Tự Lập Khi Tròn 18 Tuổi","hookQuestion":"Bạn sẽ quyết định ngành nghề thay con hay trao cho con chiếc la bàn để con tự vẽ nên tương lai của chính mình trong thời đại bùng nổ AI?","emotionalQuote":"Làm cha mẹ không phải là giữ con bên mình mãi mãi, mà là giúp con đủ vững vàng để tự bước đi – và luôn biết rằng phía sau con vẫn có một gia đình để trở về.","targetAudience":"Cha mẹ có con học THPT (Lớp 10–12), các bạn trẻ chuẩn bị thi tốt nghiệp, chọn ngành đại học, du học và chuẩn bị bước vào cuộc sống tự lập.","painPoints":["Áp lực đè nặng từ kỳ thi tốt nghiệp THPT và ma trận phương thức tuyển sinh đại học đổi mới theo GDPT 2018.","Hoang mang không biết chọn ngành gì trước làn sóng AI làm thay đổi toàn bộ thị trường lao động.","Xung đột gay gắt giữa ước mơ của con và kỳ vọng ổn định của cha mẹ.","Con thiếu hụt nghiêm trọng các kỹ năng sống thực tế: quản lý tài chính, hiểu biết pháp lý công dân tuổi 18, sinh hoạt tự lập.","Sự xa cách thế hệ ngày càng lớn khi con chuẩn bị rời xa vòng tay gia đình."],"coreSolution":"Ứng dụng Định Hướng Thanh Niên 16–18 Tuổi cung cấp Bản đồ học tập & Trạm thi tuyển sinh GDPT 2018, La bàn định hướng 3 kịch bản tương lai Holland-Ikigai, Kịch bản đối thoại GROW & NVC, Thỏa thuận gia đình tự nguyện và Hành trang pháp lý công dân tuổi 18.","keyFeatures":[{"title":"Trạm Tổng Quan Gia Đình (Home Dashboard & Weekly Insight)","description":"Bức tranh toàn cảnh hàng tuần trên 5 khía cạnh: Học tập, Định hướng, Kết nối, Sức khỏe và Trưởng thành cùng 3 việc cha mẹ làm ngay.","iconName":"Compass"},{"title":"Bản Đồ Học Tập & Trạm Thi/Tuyển Sinh GDPT 2018","description":"Nắm bắt lộ trình môn học lớp 10-12, tổ hợp xét tuyển, các mốc thi tốt nghiệp THPT và đại học mà không biến cha mẹ thành người soi xét điểm.","iconName":"GraduationCap"},{"title":"La Bàn Định Hướng 3 Kịch Bản Tương Lai Holland - Ikigai","description":"Khám phá giao điểm giữa đam mê và cơ hội thị trường; mô phỏng 3 kịch bản tương lai (An toàn, Khám phá, Đột phá) để cả nhà cùng thảo luận.","iconName":"Target"},{"title":"Cầu Nối Cha Mẹ - Con Bằng Khung GROW & NVC","description":"Hướng dẫn cải thiện tương tác gia đình, tôn trọng không gian riêng tư và giải quyết mâu thuẫn thế hệ dựa trên sự lắng nghe không phán xét.","iconName":"HeartHandshake"},{"title":"Trợ Lý Giao Tiếp AI 'Nói Sao Với Con?'","description":"Nhập tình huống khó xử (con chọn ngành khác ý, áp lực thức khuya, khép kín); AI gợi ý nguyên nhân sâu xa và câu mở đầu ấm áp.","iconName":"Bot"},{"title":"Thỏa Thuận Gia Đình & Xây Dựng Ranh Giới Tự Nguyện","description":"Thiết lập cam kết tự giác về giờ giấc, tài chính tiêu vặt, điện thoại và việc nhà dựa trên sự tôn trọng thay vì áp đặt mệnh lệnh.","iconName":"FileCheck"},{"title":"Theo Dõi Sức Khỏe, Giấc Ngủ & Dinh Dưỡng Mùa Thi","description":"Biểu đồ xu hướng giấc ngủ, chỉ số căng thẳng và thực đơn bổ não tăng cường trí nhớ, phục hồi thể lực mùa thi cử.","iconName":"Activity"},{"title":"Đồng Hành Đời Sống Số & Dấu Chân Kỹ Thuật Số","description":"Xây dựng năng lực số vững vàng, bảo vệ danh tính mạng cá nhân và phòng tránh các nguy cơ lừa đảo tài chính công nghệ cao.","iconName":"ShieldAlert"},{"title":"Hành Trang Bước Vào Tuổi 18 Pháp Lý Công Dân","description":"Checklist kiến thức công dân thực tế: tài khoản ngân hàng, VNeID, hợp đồng thuê trọ, quyền và nghĩa vụ pháp luật khi tròn 18 tuổi.","iconName":"CheckCircle"},{"title":"Trợ Lý Đồng Hành 24/7 & Nhật Ký Gắn Kết Trưởng Thành","description":"Người cố vấn AI luôn lắng nghe kết hợp nhật ký gia đình lưu lại các quyết định mang tính bước ngoặt của cuộc đời con.","iconName":"BookOpen"}],"uniqueHighlights":["Mô hình 3 kịch bản tương lai giải tỏa bế tắc chọn ngành nghề","Trợ lý AI 'Nói sao với con' giúp cha mẹ phá vỡ sự im lặng","Checklist hành trang pháp lý công dân tuổi 18 thực tiễn nhất","Bản đồ theo dõi tuyển sinh GDPT 2018 chính xác từng mốc thời gian"],"videoDuration":"2:55","videoTagline":"10 tính năng cốt lõi đồng hành bứt phá THPT và vững vàng bước vào đời cùng thanh niên 16–18 tuổi","videoScenes":[{"time":"0:00","title":"Trạm Tổng quan Gia đình (Home Dashboard & Weekly Insight)","description":"Sau Nuôi dưỡng bé 0–60 tháng, Nuôi dạy con 6–11 tuổi và Thấu hiểu thiếu niên 12–15 tuổi, đây là mảnh ghép cuối cùng Định hướng thanh niên 16–18 tuổi được thiết kế với mục đích chuyển từ 'quản lý' sang 'đồng hành cùng con': Cung cấp bức tranh tổng thể hàng tuần của con trên 5 khía cạnh và gợi ý 3 việc cụ thể cha mẹ có thể làm ngay."},{"time":"0:15","title":"Bản đồ Học tập & Trạm Thi/Tuyển sinh (Academic & Exam Hub)","description":"Giúp cha mẹ nắm bắt chương trình GDPT 2018 (lớp 10–12), tổ hợp môn học, xu hướng tiến bộ, cùng các mốc thời gian thi tốt nghiệp THPT và xét tuyển đại học mà không biến cha mẹ thành 'người giám sát điểm số'."},{"time":"0:30","title":"La bàn Định hướng & Kịch bản Tương lai (Career & Future Direction)","description":"Tích hợp các công cụ khám phá năng lực, sở thích (Holland RIASEC, Ikigai) và gợi ý 3 kịch bản tương lai (An toàn, Khám phá, Đột phá) để gia đình cùng thảo luận hướng đi thay vì áp đặt ngành học."},{"time":"0:45","title":"Cầu nối Cha mẹ – Con (Parent–Teen Connection)","description":"Bộ hướng dẫn giúp cải thiện tương tác gia đình, tôn trọng quyền riêng tư và ứng dụng phương pháp Giao tiếp phi bạo lực (NVC) cùng mô hình GROW để giải quyết các xung đột tuổi mới lớn."},{"time":"1:00","title":"Trợ lý Giao tiếp AI ('Nói sao với con?')","description":"Công cụ tương tác cho phép cha mẹ nhập tình huống khó khăn thực tế (như con khép kín, áp lực thi cử, thức khuya, chọn ngành khác ý muốn gia đình) và nhận gợi ý về nguyên nhân, điều nên tránh, cùng câu mở đầu không phán xét."},{"time":"1:15","title":"Thỏa thuận Gia đình (Family Boundary Builder)","description":"Hỗ trợ cha mẹ và con cùng xây dựng các 'thỏa thuận chung' tự nguyện về giờ giấc, sử dụng điện thoại, tài chính tiêu vặt và việc nhà dựa trên tinh thần trách nhiệm thay vì quy tắc ép buộc."},{"time":"1:30","title":"Theo dõi Sức khỏe, Giấc ngủ & Dinh dưỡng (Health & Wellness Tracker)","description":"Theo dõi xu hướng giấc ngủ, thời lượng dùng màn hình, chế độ dinh dưỡng mùa thi và biểu hiện căng thẳng của con dưới dạng biểu đồ xu hướng để phát hiện sớm các dấu hiệu bất thường."},{"time":"1:45","title":"Đồng hành Đời sống số (Digital Life Guidance)","description":"Hướng dẫn cha mẹ cách xây dựng năng lực số cho con, thảo luận về an toàn mạng xã hội, bắt nạt trên mạng, lừa đảo trực tuyến và dấu chân kỹ thuật số dựa trên sự tin tưởng."},{"time":"2:00","title":"Hành trang Bước vào Tuổi 18 (Age 18 Citizenship Prep)","description":"Danh mục kiểm tra và cung cấp kiến thức pháp lý, công dân cơ bản khi con tròn 18 tuổi (giấy tờ cá nhân, VNeID, nhận thức pháp luật, an toàn tài chính, tài khoản cá nhân)."},{"time":"2:15","title":"Trợ lý đồng hành 24/7 & Nhật ký Đồng hành","description":"Trợ lý AI trung tâm đóng vai trò người cố vấn bình tĩnh, đưa ra lời khuyên dựa trên bằng chứng, kết hợp với Nhật ký ghi lại các cột mốc, cảm xúc và quyết định quan trọng của gia đình."},{"time":"2:30","title":"Trọn bộ 4 ứng dụng – Hành trình 0–18 tuổi khôn lớn cùng con","description":"Trọn bộ 4 ứng dụng – 4 giai đoạn – một hành trình 0–18 tuổi cùng cha mẹ đi qua từng chặng đường lớn lên của con. Nếu 5 năm đầu là chăm sóc, 6–11 tuổi là nuôi dạy, 12–15 tuổi là thấu hiểu, thì 16–18 tuổi là trao quyền và đồng hành. Cha mẹ không phải là giữ con bên mình mãi mãi, mà là giúp con đủ vững vàng để tự bước đi – và luôn biết rằng phía sau mình vẫn có một gia đình để trở về."}],"theme":{"from":"from-indigo-500","to":"to-purple-600","accent":"text-indigo-400","badgeBg":"bg-indigo-500/10","badgeText":"text-indigo-300","badgeBorder":"border-indigo-500/30","glowColor":"rgba(99, 102, 241, 0.35)","buttonGradient":"from-indigo-500 via-purple-500 to-pink-500"}}$json$::jsonb)
on conflict (id) do update set number=excluded.number, name=excluded.name, stage_name=excluded.stage_name, age_range=excluded.age_range, url=excluded.url, data=excluded.data, updated_at=now();

-- 6) Vài đánh giá mẫu
insert into public.reviews (app_id, author_name, rating, content)
select * from (values
  ('nuoi-duong-be-0-60', 'Mẹ Bắp', 5, 'Nút SOS ngoại tuyến rất hữu ích, tối con sốt mình mở được ngay dù mất mạng.'),
  ('nuoi-day-tre-6-11', 'Bố Tí', 5, 'Kịch bản giao tiếp giúp giờ học tối nhẹ nhàng hơn hẳn.'),
  ('thau-hieu-thieu-nien-12-15', 'Chị Lan', 4, 'Phần khiên an toàn số rất thực tế cho phụ huynh có con tuổi dậy thì.')
) v(app_id, author_name, rating, content)
where not exists (select 1 from public.reviews);
